 r=mp.mpf(1);l,d,z,R=map(mp.mpf,(l,d,z,R))
 f=lambda h,r:r/(h+mp.sqrt(h*h+r*r))
 x=f(l,1);y=f(l+d,R);u=f(z+d,1);v=f(z,R);q=f(d,R-1)
 A=[mp.mpf(1)];B=A[:]
